INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000213',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss the German health system at B2","Use Gesundheitssystem vocabulary","Talk about healthcare reform"],"explanation":{"intro":"Health system vocabulary covers German healthcare structure, insurance, and reform debates at B2.","culturalNote":"Germany has a dual-system: gesetzliche Krankenversicherung (GKV — statutory health insurance, ~90% of population, ~100 Krankenkassen) and private Krankenversicherung (PKV — ~10%). Bismarckian model. Key issues: Zweiklassenmedizin (two-tier medicine — private vs. statutory), Pflegepersonalmangel (nursing shortage), steigende Beiträge (rising contribution rates), Digitalisierung im Gesundheitswesen (Elektronische Patientenakte — ePA)."},"examples":[{"german":"Das deutsche Gesundheitssystem steht vor der Herausforderung, medizinische Qualität, Kosteneffizienz und Zugangsgerechtigkeit gleichzeitig zu gewährleisten.","english":"The German health system faces the challenge of simultaneously ensuring medical quality, cost efficiency, and equity of access."},{"german":"Die Finanzierungslücke in der gesetzlichen Krankenversicherung spiegelt strukturelle Dysfunktionen wider, die durch punktuelle Reformen allein nicht zu schließen sind.","english":"The financing gap in statutory health insurance reflects structural dysfunctions that cannot be closed by piecemeal reforms alone."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss the German health system, insurance, and healthcare reform at B2."}}',
'{"items":[{"word":"gleichzeitig","translation":"simultaneously","pronunciation":"GLYKH-tsy-tikh","example":"Gleichzeitig gewährleisten."},{"word":"die Zugangsgerechtigkeit","translation":"equity of access","pronunciation":"dee TSOO-ganks-geh-rekh-tikh-kyt","example":"Zugangsgerechtigkeit."},{"word":"die Finanzierungslücke","translation":"financing gap","pronunciation":"dee fi-nan-TSEER-oonks-lü-keh","example":"Finanzierungslücke schließen."},{"word":"die Dysfunktion","translation":"dysfunction","pronunciation":"dee düs-foonk-TSYOHN","example":"Strukturelle Dysfunktionen."},{"word":"punktuell","translation":"piecemeal/selective","pronunciation":"poonk-too-EL","example":"Punktuelle Reformen."},{"word":"widerspiegeln","translation":"to reflect","pronunciation":"VI-der-shpee-geln","example":"Dysfunktionen widerspiegeln."}]}',
'{"title":"Durch ... allein nicht — not by ... alone (negated single-means)","pattern":"nicht durch X allein = not by X alone (X is insufficient on its own)","explanation":"Durch X allein nicht = not by X alone (X is necessary but insufficient). Nicht durch punktuelle Reformen allein zu schließen = not to be closed by piecemeal reforms alone. Allein (alone, solely) restricts to one means; the negation says it is insufficient. This pattern appears in academic argument to say a single intervention cannot solve a complex problem. Compare: nicht nur durch X (not only through X — implies Y is also needed), weder durch X noch durch Y (neither through X nor Y — both excluded).","examples":[{"sentence":"Das Problem ist nicht durch technische Maßnahmen allein zu lösen.","translation":"The problem cannot be solved by technical measures alone."},{"sentence":"Wirtschaftlicher Erfolg ist nicht durch Kostensenkung allein zu erreichen.","translation":"Economic success cannot be achieved through cost reduction alone."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Punktuell'' means?","options":["piecemeal/selective","sporadic","partial","isolated"],"correctAnswer":"piecemeal/selective"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The German health system faces the challenge of simultaneously ensuring medical quality, cost efficiency, and equity of access.","options":["Das deutsche Gesundheitssystem steht vor der Herausforderung, medizinische Qualität, Kosteneffizienz und Zugangsgerechtigkeit gleichzeitig zu gewährleisten.","Das Gesundheitssystem muss qualitativ, effizient und gerecht sein.","Qualität, Effizienz und Gerechtigkeit sind Ziele des Gesundheitssystems.","Gesundheitsversorgung muss für alle zugänglich und erschwinglich sein."],"correctAnswer":"Das deutsche Gesundheitssystem steht vor der Herausforderung, medizinische Qualität, Kosteneffizienz und Zugangsgerechtigkeit gleichzeitig zu gewährleisten."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Problem ist nicht durch technische Maßnahmen allein zu ___.","options":["lösen","beheben","beseitigen","lösen"],"correctAnswer":"lösen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Economic success cannot be achieved through cost reduction alone","wordBankItems":["Wirtschaftlicher","Erfolg","ist","nicht","durch","Kostensenkung","allein","zu","erreichen","."],"correctAnswer":"Wirtschaftlicher Erfolg ist nicht durch Kostensenkung allein zu erreichen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Zugangsgerechtigkeit'' means?","options":["equity of access","equal access","access equality","fair access"],"correctAnswer":"equity of access"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000214',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss medicine and technology at B2","Use Medizintechnologie vocabulary","Talk about medical innovation"],"explanation":{"intro":"Medicine and technology vocabulary covers medical technology, personalised medicine, and healthcare digitalisation at B2.","culturalNote":"Germany is a leader in Medizintechnologie (medical technology — Siemens Healthineers, B. Braun, Karl Storz). Key developments: KI in der Diagnostik (AI in diagnostics), Telemedizin (telemedicine — accelerated by COVID), personalisierte Medizin (personalised medicine — genomics, precision oncology), Roboterchirurgie (robotic surgery). Key issues: Datenschutz in digitaler Medizin, Zulassungsverfahren (approval procedures), Kostenübernahme durch Kassen (reimbursement by insurers)."},"examples":[{"german":"Personalisierte Medizin nutzt genomische Daten und KI-Algorithmen, um Therapien präzise auf den Patienten zuzuschneiden und Nebenwirkungen zu minimieren.","english":"Personalised medicine uses genomic data and AI algorithms to precisely tailor therapies to the patient and minimise side effects."},{"german":"Telemedizin überbrückt geografische Barrieren in der Gesundheitsversorgung, wirft jedoch Fragen der Datensicherheit und der persönlichen Arzt-Patienten-Beziehung auf.","english":"Telemedicine bridges geographical barriers in healthcare, but raises questions about data security and the personal doctor-patient relationship."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss medical technology, personalised medicine, and telemedicine at B2."}}',
'{"items":[{"word":"zuschneiden auf","translation":"to tailor to","pronunciation":"TSOO-shny-den owf","example":"Auf den Patienten zuschneiden."},{"word":"minimieren","translation":"to minimise","pronunciation":"mi-ni-MEER-en","example":"Nebenwirkungen minimieren."},{"word":"überbrücken","translation":"to bridge","pronunciation":"ü-ber-BRÜK-en","example":"Barrieren überbrücken."},{"word":"geografisch","translation":"geographical","pronunciation":"geh-o-GRAH-fish","example":"Geografische Barrieren."},{"word":"aufwerfen","translation":"to raise (questions)","pronunciation":"OWF-ver-fen","example":"Fragen aufwerfen."},{"word":"die Nebenwirkung","translation":"side effect","pronunciation":"dee NAY-ben-vir-koong","example":"Nebenwirkungen minimieren."}]}',
'{"title":"Zuschneiden auf — to tailor to (separable)","pattern":"etwas auf jemanden/etwas zuschneiden = to tailor something to someone/something (separable)","explanation":"Zuschneiden auf + accusative (separable) = to tailor to, to cut to fit. Therapien auf den Patienten zuschneiden = to tailor therapies to the patient. Present: schneidet zu. Perfect: hat zugeschnitten. Comes from cutting fabric/clothing to fit (Schneiden = to cut). Used figuratively for adapting solutions precisely. Compare: anpassen an (to adapt to — more general), abstimmen auf (to tune/adjust to — for coordination), individualisieren (to individualise).","examples":[{"sentence":"Das Programm wurde auf die Bedürfnisse der Teilnehmer zugeschnitten.","translation":"The programme was tailored to the needs of the participants."},{"sentence":"Die Maßnahmen müssen auf die spezifische Situation zugeschnitten werden.","translation":"The measures must be tailored to the specific situation."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Überbrücken'' means?","options":["to bridge","to span","to cross","to overcome"],"correctAnswer":"to bridge"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Personalised medicine uses genomic data and AI algorithms to precisely tailor therapies to the patient and minimise side effects.","options":["Personalisierte Medizin nutzt genomische Daten und KI-Algorithmen, um Therapien präzise auf den Patienten zuzuschneiden und Nebenwirkungen zu minimieren.","Personalisierte Medizin passt Behandlungen an jeden Patienten an.","KI hilft Ärzten, Therapien besser auf Patienten abzustimmen.","Genomische Daten ermöglichen präzise medizinische Behandlungen."],"correctAnswer":"Personalisierte Medizin nutzt genomische Daten und KI-Algorithmen, um Therapien präzise auf den Patienten zuzuschneiden und Nebenwirkungen zu minimieren."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Programm wurde auf die Bedürfnisse der Teilnehmer ___.","options":["zugeschnitten","angepasst","abgestimmt","gestaltet"],"correctAnswer":"zugeschnitten"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The measures must be tailored to the specific situation","wordBankItems":["Die","Maßnahmen","müssen","auf","die","spezifische","Situation","zugeschnitten","werden","."],"correctAnswer":"Die Maßnahmen müssen auf die spezifische Situation zugeschnitten werden ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Minimieren'' means?","options":["to minimise","to reduce","to limit","to decrease"],"correctAnswer":"to minimise"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000215',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss mental health at B2","Use psychische Gesundheit vocabulary","Talk about mental health policy"],"explanation":{"intro":"Mental health vocabulary covers psychological well-being, mental health disorders, and treatment approaches at B2.","culturalNote":"Mental health in Germany: ~27% of adults affected by a mental disorder per year (Bundesgesundheitssurvey). Most common: Depression, Angststörungen (anxiety disorders), Sucht (addiction). Stigmatisierung (stigmatisation) remains a barrier. Key institutions: Psychiatrische Kliniken, Psychotherapeuten (long waiting times — Wartezeiten on therapy). German Mental Health Act (PsychKG) varies by state. Burnout became prominent debate in Germany ~2010."},"examples":[{"german":"Psychische Erkrankungen sind nach wie vor stigmatisiert, was Betroffene daran hindert, rechtzeitig professionelle Hilfe in Anspruch zu nehmen.","english":"Mental disorders are still stigmatised, which prevents those affected from seeking professional help in time."},{"german":"Eine evidenzbasierte Versorgung psychischer Erkrankungen erfordert nicht nur ausreichende Therapieplätze, sondern auch gesellschaftliche Entstigmatisierung und Prävention.","english":"Evidence-based care for mental disorders requires not only adequate therapy places, but also social destigmatisation and prevention."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss mental health, stigmatisation, and mental health policy at B2."}}',
'{"items":[{"word":"stigmatisiert","translation":"stigmatised","pronunciation":"shtig-mah-ti-ZEERT","example":"Stigmatisiert sein."},{"word":"hindern an","translation":"to prevent from","pronunciation":"HIN-dern an","example":"Jemanden hindern an."},{"word":"in Anspruch nehmen","translation":"to make use of/seek","pronunciation":"in AN-shprookh NAY-men","example":"Hilfe in Anspruch nehmen."},{"word":"evidenzbasiert","translation":"evidence-based","pronunciation":"e-vi-DENTS-bah-zeert","example":"Evidenzbasierte Versorgung."},{"word":"ausreichend","translation":"adequate/sufficient","pronunciation":"OWS-ry-khend","example":"Ausreichende Therapieplätze."},{"word":"die Entstigmatisierung","translation":"destigmatisation","pronunciation":"dee ent-shtig-mah-ti-ZEER-oong","example":"Gesellschaftliche Entstigmatisierung."}]}',
'{"title":"Hindern an — to prevent from (doing)","pattern":"jemanden an etwas (Dativ) hindern = to prevent someone from something; jemanden hindern, etwas zu tun = to prevent from doing","explanation":"Hindern an + dative = to prevent from, to hinder in. Stigmatisierung hindert Betroffene daran, Hilfe zu suchen = Stigmatisation prevents those affected from seeking help. Construction: jemanden daran hindern, zu + Infinitiv (the daran is an anticipatory pronoun pointing to the zu-infinitive clause). Without the infinitive: hindern an + dative noun (Hindernis an der Arbeit = obstacle to work). Compare: abhalten von (to deter from), aufhalten (to stop/detain), verhindern (to prevent — more absolute, thing prevented entirely).","examples":[{"sentence":"Bürokratie hindert Unternehmen daran, schnell zu reagieren.","translation":"Bureaucracy prevents companies from reacting quickly."},{"sentence":"Nichts hindert uns daran, jetzt zu beginnen.","translation":"Nothing prevents us from starting now."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Ausreichend'' means?","options":["adequate/sufficient","enough","satisfactory","ample"],"correctAnswer":"adequate/sufficient"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Mental disorders are still stigmatised, which prevents those affected from seeking professional help in time.","options":["Psychische Erkrankungen sind nach wie vor stigmatisiert, was Betroffene daran hindert, rechtzeitig professionelle Hilfe in Anspruch zu nehmen.","Stigma verhindert, dass Betroffene Hilfe suchen.","Viele Menschen mit psychischen Erkrankungen suchen keine Hilfe.","Stigmatisierung ist ein Hindernis für die psychische Gesundheitsversorgung."],"correctAnswer":"Psychische Erkrankungen sind nach wie vor stigmatisiert, was Betroffene daran hindert, rechtzeitig professionelle Hilfe in Anspruch zu nehmen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Bürokratie hindert Unternehmen daran, schnell zu ___.","options":["reagieren","handeln","agieren","antworten"],"correctAnswer":"reagieren"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Nothing prevents us from starting now","wordBankItems":["Nichts","hindert","uns","daran",",","jetzt","zu","beginnen","."],"correctAnswer":"Nichts hindert uns daran , jetzt zu beginnen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''In Anspruch nehmen'' means?","options":["to make use of/seek","to claim","to utilise","to access"],"correctAnswer":"to make use of/seek"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000216',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss public health at B2","Use öffentliche Gesundheit vocabulary","Talk about prevention and epidemiology"],"explanation":{"intro":"Public health vocabulary covers epidemiology, prevention, and health promotion at B2.","culturalNote":"Public Health (Öffentliche Gesundheit) in Germany: Robert-Koch-Institut (RKI) — national public health institute (gained prominence during COVID-19). Key areas: Prävention, Gesundheitsförderung (health promotion), Epidemiologie, Bevölkerungsmedizin. Key challenge: non-communicable diseases (Herz-Kreislauf, Diabetes, Krebs — lifestyle diseases). Impfpflicht (vaccination mandate) debate. Pandemiemanagement during COVID criticised for communication failures."},"examples":[{"german":"Prävention ist gegenüber kurativer Medizin langfristig sowohl kosteneffektiver als auch wirkungsvoller, da sie das Auftreten von Krankheiten verhindert statt ihre Folgen zu behandeln.","english":"Prevention is more cost-effective and more effective in the long term compared to curative medicine, as it prevents the occurrence of diseases rather than treating their consequences."},{"german":"Gesundheitliche Ungleichheiten spiegeln sozioökonomische Disparitäten wider und können nicht allein durch medizinische Interventionen, sondern nur durch umfassende Sozialpolitik bekämpft werden.","english":"Health inequalities reflect socioeconomic disparities and can be combated not by medical interventions alone, but only through comprehensive social policy."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss public health, prevention, and health inequalities at B2."}}',
'{"items">[{"word":"kurativ","translation":"curative","pronunciation":"koo-rah-TEEF","example":"Kurative Medizin."},{"word":"das Auftreten","translation":"occurrence/appearance","pronunciation":"dahs OWF-tray-ten","example":"Auftreten von Krankheiten."},{"word":"verhindern","translation":"to prevent","pronunciation":"fer-HIN-dern","example":"Krankheiten verhindern."},{"word":"widerspiegeln","translation":"to reflect","pronunciation":"VI-der-shpee-geln","example":"Disparitäten widerspiegeln."},{"word":"bekämpfen","translation":"to combat/fight","pronunciation":"beh-KEMP-fen","example":"Ungleichheiten bekämpfen."},{"word":"umfassend","translation":"comprehensive","pronunciation":"OOM-fas-end","example":"Umfassende Sozialpolitik."}]}',
'{"title":"Gegenüber — compared to, vis-à-vis, towards (preposition)","pattern":"gegenüber + dative = compared to, in contrast to, towards (multiple meanings — context-driven)","explanation":"Gegenüber + dative (before or after noun) = 1) compared to/in contrast to (comparison: Prävention ist gegenüber kurativer Medizin besser = Prevention is better compared to curative medicine); 2) opposite (physical: gegenüber dem Bahnhof = opposite the station); 3) towards/in relation to (attitude: gegenüber Fremden misstrauisch = distrustful towards strangers). Position: after a pronoun (mir gegenüber = opposite me), before or after a noun (gegenüber dem Büro / dem Büro gegenüber). Compare: im Vergleich zu (in comparison to — more explicit comparison), im Gegensatz zu (in contrast to — stronger opposition).","examples":[{"sentence":"Gegenüber dem Vorjahr sind die Umsätze gestiegen.","translation":"Compared to the previous year, revenues have increased."},{"sentence":"Das Hotel liegt gegenüber dem Park.","translation":"The hotel is opposite the park."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Kurativ'' means?","options":["curative","healing","remedial","therapeutic"],"correctAnswer":"curative"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Prevention is more cost-effective and more effective in the long term compared to curative medicine, as it prevents the occurrence of diseases rather than treating their consequences.","options":["Prävention ist gegenüber kurativer Medizin langfristig sowohl kosteneffektiver als auch wirkungsvoller, da sie das Auftreten von Krankheiten verhindert statt ihre Folgen zu behandeln.","Vorsorge ist besser als Behandlung.","Krankheiten zu verhindern ist günstiger als sie zu behandeln.","Präventive Medizin spart langfristig Kosten."],"correctAnswer":"Prävention ist gegenüber kurativer Medizin langfristig sowohl kosteneffektiver als auch wirkungsvoller, da sie das Auftreten von Krankheiten verhindert statt ihre Folgen zu behandeln."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Gegenüber dem Vorjahr sind die Umsätze ___.","options":["gestiegen","gewachsen","erhöht","zugenommen"],"correctAnswer":"gestiegen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The hotel is opposite the park","wordBankItems":["Das","Hotel","liegt","gegenüber","dem","Park","."],"correctAnswer":"Das Hotel liegt gegenüber dem Park ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Umfassend'' means?","options":["comprehensive","extensive","broad","wide-ranging"],"correctAnswer":"comprehensive"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000217',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss the pharmaceutical industry at B2","Use Pharmaindustrie vocabulary","Talk about drug development and pricing"],"explanation":{"intro":"Pharmaceutical industry vocabulary covers drug development, clinical trials, and pharmaceutical pricing at B2.","culturalNote":"Germany is a major pharmaceutical nation: Bayer, Merck, Boehringer Ingelheim, Fresenius. AMNOG (Arzneimittelmarktneuordnungsgesetz 2011 — pharmaceutical reform) requires early benefit assessment of new drugs. Key issues: Arzneimittelpreise (drug prices), Generika (generics), Patentschutz (patent protection), klinische Studien (clinical trials), Zulassungsverfahren (EMA approval), Off-Label-Use. Antibiotic resistance (Antibiotikaresistenz) major public health concern."},"examples":[{"german":"Die Entwicklung neuer Medikamente ist ein langwieriger, kostenintensiver Prozess, der regulatorische Zulassung, klinische Studien und ethische Kontrolle erfordert.","english":"The development of new medications is a lengthy, cost-intensive process that requires regulatory approval, clinical trials, and ethical control."},{"german":"Das Spannungsfeld zwischen dem Patentschutz für Arzneimittelinnovationen und dem Recht auf erschwingliche Medikamente ist eine der zentralen gesundheitspolitischen Fragen unserer Zeit.","english":"The tension between patent protection for pharmaceutical innovations and the right to affordable medicines is one of the central health policy questions of our time."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss the pharmaceutical industry, drug development, and pricing at B2."}}',
'{"items":[{"word":"langwierig","translation":"lengthy/protracted","pronunciation":"LANG-vee-rikh","example":"Langwieriger Prozess."},{"word":"kostenintensiv","translation":"cost-intensive","pronunciation":"KOS-ten-in-ten-SEEF","example":"Kostenintensiver Prozess."},{"word":"das Spannungsfeld","translation":"tension/area of tension","pronunciation":"dahs SHPAN-oonks-felt","example":"Spannungsfeld zwischen."},{"word":"erschwinglich","translation":"affordable","pronunciation":"er-SHVING-likh","example":"Erschwingliche Medikamente."},{"word":"die Zulassung","translation":"approval/authorisation","pronunciation":"dee TSOO-las-oong","example":"Regulatorische Zulassung."},{"word":"zentral","translation":"central/key","pronunciation":"tsen-TRAHL","example":"Zentrale Fragen."}]}',
'{"title":"Das Spannungsfeld zwischen ... und — the tension between...and (area of tension)","pattern":"das Spannungsfeld zwischen X und Y = the tension between X and Y (area where two forces pull against each other)","explanation":"Das Spannungsfeld zwischen X und Y = the field of tension/the tension between X and Y. A conceptual space where two values or interests conflict. In einem Spannungsfeld stehen = to be caught in a tension. Compare: der Konflikt zwischen (the conflict between — more direct confrontation), die Spannung zwischen (the tension between — similar, but Spannungsfeld = the entire area, not just the tension itself), das Dilemma (dilemma — forced choice between two bad options).","examples":[{"sentence":"Journalisten bewegen sich im Spannungsfeld zwischen Informationspflicht und Quellenvertraulichkeit.","translation":"Journalists operate in the tension between the duty to inform and source confidentiality."},{"sentence":"Das Spannungsfeld zwischen Sicherheit und Freiheit ist ein klassisches politisches Problem.","translation":"The tension between security and freedom is a classic political problem."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Langwierig'' means?","options":["lengthy/protracted","time-consuming","prolonged","slow"],"correctAnswer":"lengthy/protracted"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The tension between patent protection for pharmaceutical innovations and the right to affordable medicines is one of the central health policy questions of our time.","options":["Das Spannungsfeld zwischen dem Patentschutz für Arzneimittelinnovationen und dem Recht auf erschwingliche Medikamente ist eine der zentralen gesundheitspolitischen Fragen unserer Zeit.","Patentschutz und Erschwinglichkeit von Medikamenten sind im Widerspruch.","Pharmazeutische Innovationen müssen geschützt und gleichzeitig zugänglich sein.","Medikamente sollten erschwinglich sein, obwohl Forschung teuer ist."],"correctAnswer":"Das Spannungsfeld zwischen dem Patentschutz für Arzneimittelinnovationen und dem Recht auf erschwingliche Medikamente ist eine der zentralen gesundheitspolitischen Fragen unserer Zeit."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Journalisten bewegen sich im Spannungsfeld zwischen Informationspflicht und Quellen___.","options":["vertraulichkeit","schutz","geheimhaltung","sicherheit"],"correctAnswer":"vertraulichkeit"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The tension between security and freedom is a classic political problem","wordBankItems":["Das","Spannungsfeld","zwischen","Sicherheit","und","Freiheit","ist","ein","klassisches","politisches","Problem","."],"correctAnswer":"Das Spannungsfeld zwischen Sicherheit und Freiheit ist ein klassisches politisches Problem ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Erschwinglich'' means?","options":["affordable","reasonable","accessible","cheap"],"correctAnswer":"affordable"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000218',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss bioethics at B2","Use Bioethik vocabulary","Talk about ethical issues in biology and medicine"],"explanation":{"intro":"Bioethics vocabulary covers ethical issues in medicine, genetics, and life sciences at B2.","culturalNote":"Bioethik (bioethics) in Germany is deeply influenced by Germany''s history (Nazi medicine). Key institutions: Deutscher Ethikrat (German Ethics Council — advises parliament and government). Key issues: Stammzellenforschung (stem cell research — strict rules, Stammzellengesetz 2002), Präimplantationsdiagnostik (PGD — pre-implantation genetic diagnosis, limited use), CRISPR-Keimbahneingriffe (germline editing — banned), Sterbehilfe (euthanasia — debate ongoing since BVerfG 2020). Patientenautonomie (patient autonomy) growing importance."},"examples":[{"german":"Bioethische Debatten illustrieren das Grunddilemma zwischen dem Streben nach medizinischem Fortschritt und der Wahrung der Würde und Integrität des menschlichen Lebens.","english":"Bioethical debates illustrate the fundamental dilemma between the striving for medical progress and the preservation of the dignity and integrity of human life."},{"german":"Die rechtliche Regulierung der Genomchirurgie steht vor dem Problem, technologischen Entwicklungen, die schneller voranschreiten als die gesellschaftliche Debatte, einen ethischen Rahmen zu geben.","english":"The legal regulation of genome surgery faces the problem of giving an ethical framework to technological developments that advance more rapidly than societal debate."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss bioethics, genome editing, and medical ethics at B2."}}',
'{"items":[{"word":"das Streben","translation":"striving/aspiration","pronunciation":"dahs SHTRAY-ben","example":"Das Streben nach Fortschritt."},{"word":"die Wahrung","translation":"preservation/safeguarding","pronunciation":"dee VAH-roong","example":"Wahrung der Würde."},{"word":"die Integrität","translation":"integrity","pronunciation":"dee in-teh-gri-TÄT","example":"Integrität des Lebens."},{"word":"voranschreiten","translation":"to advance/progress","pronunciation":"for-AN-shry-ten","example":"Schnell voranschreiten."},{"word":"der Rahmen","translation":"framework","pronunciation":"dayr RAH-men","example":"Ethischen Rahmen geben."},{"word":"illustrieren","translation":"to illustrate","pronunciation":"il-oos-TREER-en","example":"Ein Dilemma illustrieren."}]}',
'{"title":"Voranschreiten — to advance, progress (intransitive)","pattern":"etwas schreitet voran = something advances/progresses (separable — used for processes, developments)","explanation":"Voranschreiten (separable) = to advance, make progress (used for processes, technology, disease, development — not for people advancing through a crowd). Die Technologie schreitet voran = The technology advances. Perfect: ist vorangeschritten (sein — movement/change of state). Compare: Fortschritte machen (to make progress — with a subject that is an agent), sich entwickeln (to develop — more about change), zunehmen (to increase — for quantities).","examples":[{"sentence":"Die Digitalisierung schreitet unaufhaltsam voran.","translation":"Digitalisation is advancing unstoppably."},{"sentence":"Mit voranschreitender Erkrankung werden die Symptome stärker.","translation":"As the disease advances, the symptoms become more severe."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Streben'' means?","options":["striving/aspiration","effort","ambition","pursuit"],"correctAnswer":"striving/aspiration"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Bioethical debates illustrate the fundamental dilemma between the striving for medical progress and the preservation of the dignity and integrity of human life.","options":["Bioethische Debatten illustrieren das Grunddilemma zwischen dem Streben nach medizinischem Fortschritt und der Wahrung der Würde und Integrität des menschlichen Lebens.","Bioethik beschäftigt sich mit dem Verhältnis von Medizin und Menschenwürde.","Medizinischer Fortschritt und Menschenwürde stehen in einem Dilemma.","Das Dilemma der Bioethik liegt zwischen Fortschritt und Würde."],"correctAnswer":"Bioethische Debatten illustrieren das Grunddilemma zwischen dem Streben nach medizinischem Fortschritt und der Wahrung der Würde und Integrität des menschlichen Lebens."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Digitalisierung schreitet unaufhaltsam ___.","options":["voran","fort","weiter","vorwärts"],"correctAnswer":"voran"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: As the disease advances the symptoms become more severe","wordBankItems":["Mit","voranschreitender","Erkrankung","werden","die","Symptome","stärker","."],"correctAnswer":"Mit voranschreitender Erkrankung werden die Symptome stärker ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Wahrung'' means?","options":["preservation/safeguarding","protection","maintenance","defence"],"correctAnswer":"preservation/safeguarding"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000219',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss demographics at B2","Use Demografie vocabulary","Talk about population change"],"explanation":{"intro":"Demographics vocabulary covers population trends, birth rates, migration, and their consequences at B2.","culturalNote":"Germany''s Demografischer Wandel (demographic change): falling birth rate (Geburtenrate ~1.5, below replacement ~2.1), ageing population (Alterung der Gesellschaft), rising Lebenserwartung (life expectancy — now ~81). Net migration partly compensates. Key consequences: Fachkräftemangel, Rentenfinanzierung, Pflegebedarf, Schrumpfung ländlicher Räume (shrinking rural areas). Bevölkerungsprognosen (population forecasts) by Statistisches Bundesamt."},"examples":[{"german":"Der demografische Wandel stellt die sozialen Sicherungssysteme vor strukturelle Herausforderungen, da eine schrumpfende Erwerbsbevölkerung eine wachsende Zahl von Rentenempfängern finanzieren muss.","english":"Demographic change poses structural challenges to the social security systems, as a shrinking working-age population must finance a growing number of pension recipients."},{"german":"Gezielte Einwanderungspolitik wird als ein möglicher Ausgleich für den demografischen Rückgang angesehen, löst jedoch nicht alle strukturellen Probleme des Sozialstaats.","english":"Targeted immigration policy is regarded as a possible counterbalance to demographic decline, but does not resolve all structural problems of the welfare state."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss demographics, demographic change, and its policy consequences at B2."}}',
'{"items":[{"word":"der Rentenempfänger","translation":"pension recipient","pronunciation":"dayr REN-ten-emp-feng-er","example":"Wachsende Rentenempfänger."},{"word":"gezielt","translation":"targeted/purposeful","pronunciation":"geh-TSEELT","example":"Gezielte Einwanderungspolitik."},{"word":"der Ausgleich","translation":"counterbalance/compensation","pronunciation":"dayr OWS-glykh","example":"Als Ausgleich dienen."},{"word":"ansehen als","translation":"to regard as","pronunciation":"AN-zay-en als","example":"Als Ausgleich angesehen."},{"word":"der Rückgang","translation":"decline","pronunciation":"dayr RÜK-gang","example":"Demografischer Rückgang."},{"word":"auflösen","translation":"to resolve/dissolve","pronunciation":"OWF-lö-zen","example":"Probleme auflösen."}]}',
'{"title":"Als ... angesehen werden — to be regarded as (passive perception)","pattern":"als X angesehen werden = to be regarded as X (passive — the subject is how others perceive/classify it)","explanation":"Als X angesehen werden = to be regarded as X (passive construction). Einwanderungspolitik wird als Ausgleich angesehen = Immigration policy is regarded as a counterbalance. It is a perception/classification by others (or generally). Compare with active: jemanden als X ansehen (to regard someone as X). Also: als X gelten (to be considered X — less passive, more about general status), als X bezeichnet werden (to be described as X — more linguistic label).","examples":[{"sentence":"Der Vorschlag wird allgemein als zu ambitioniert angesehen.","translation":"The proposal is generally regarded as too ambitious."},{"sentence":"Er wird in der Branche als Experte angesehen.","translation":"He is regarded in the industry as an expert."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Gezielt'' means?","options":["targeted/purposeful","deliberate","focused","specific"],"correctAnswer":"targeted/purposeful"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Targeted immigration policy is regarded as a possible counterbalance to demographic decline, but does not resolve all structural problems of the welfare state.","options":["Gezielte Einwanderungspolitik wird als ein möglicher Ausgleich für den demografischen Rückgang angesehen, löst jedoch nicht alle strukturellen Probleme des Sozialstaats.","Einwanderung kann den demografischen Wandel teilweise ausgleichen.","Migration allein löst die Probleme des demografischen Wandels nicht.","Einwanderungspolitik ist ein Instrument gegen den demografischen Rückgang."],"correctAnswer":"Gezielte Einwanderungspolitik wird als ein möglicher Ausgleich für den demografischen Rückgang angesehen, löst jedoch nicht alle strukturellen Probleme des Sozialstaats."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Der Vorschlag wird allgemein als zu ambitioniert ___.","options":["angesehen","betrachtet","eingeschätzt","bewertet"],"correctAnswer":"angesehen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: He is regarded in the industry as an expert","wordBankItems":["Er","wird","in","der","Branche","als","Experte","angesehen","."],"correctAnswer":"Er wird in der Branche als Experte angesehen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Der Ausgleich'' means?","options":["counterbalance/compensation","balance","equalisation","offset"],"correctAnswer":"counterbalance/compensation"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000021a',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss the ageing society at B2","Use Altersgesellschaft vocabulary","Talk about eldercare and silver economy"],"explanation":{"intro":"Ageing society vocabulary covers eldercare, the silver economy, and age-related policy at B2.","culturalNote":"Germany is one of the oldest societies globally: median age ~46. Key issues: Pflegebedürftigkeit (need for care — ~5 million people), Pflegeheime vs. ambulante Pflege (residential vs. home care), Pflegenotstand (care emergency — shortage of Pflegekräfte), Silberwirtschaft (silver economy — products/services for older people, growing market). Generationenpolitik (generational policy). Renteneintrittsalter (retirement age) raised to 67. Frühere Rente (earlier retirement) debate (Rente mit 63)."},"examples":[{"german":"Die wachsende Zahl pflegebedürftiger Menschen stellt das Pflegesystem vor kaum bewältigbare Herausforderungen und macht einen grundlegenden Umbau der Pflegefinanzierung unumgänglich.","english":"The growing number of people in need of care poses barely manageable challenges to the care system and makes a fundamental restructuring of care financing inescapable."},{"german":"Altersgerechte Stadtentwicklung zielt darauf ab, öffentliche Räume, Wohnverhältnisse und Infrastrukturen so zu gestalten, dass ein selbstbestimmtes Leben bis ins hohe Alter möglich bleibt.","english":"Age-appropriate urban development aims to design public spaces, housing conditions, and infrastructure in such a way that self-determined life remains possible into old age."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss the ageing society, eldercare, and age-related urban planning at B2."}}',
'{"items":[{"word":"unumgänglich","translation":"inescapable/unavoidable","pronunciation":"OON-oom-geng-likh","example":"Unumgänglich machen."},{"word":"der Umbau","translation":"restructuring/transformation","pronunciation":"dayr OOM-bow","example":"Grundlegender Umbau."},{"word":"altersgerecht","translation":"age-appropriate","pronunciation":"AL-ters-geh-rekht","example":"Altersgerechte Stadtentwicklung."},{"word":"selbstbestimmt","translation":"self-determined","pronunciation":"ZELPST-beh-shtimt","example":"Selbstbestimmtes Leben."},{"word":"bewältigbar","translation":"manageable","pronunciation":"beh-VEL-tikh-bahr","example":"Kaum bewältigbare Herausforderungen."},{"word":"die Pflegebedürftigkeit","translation":"need for care","pronunciation":"dee PFLAY-geh-beh-dürf-tikh-kyt","example":"Pflegebedürftigkeit."}]}',
'{"title":"Unumgänglich machen — to make inescapable, to necessitate","pattern":"etwas unumgänglich machen = to make something inescapable, to necessitate (unavoidable consequence)","explanation":"Unumgänglich = inescapable, unavoidable. Etw. unumgänglich machen = to make something inescapable. Die wachsende Zahl macht Umbau unumgänglich = The growing number makes restructuring inescapable. This expresses logical/practical necessity: given the circumstances, something cannot be avoided. Compare: notwendig machen (to make necessary — less absolute), erzwingen (to force/compel — more active), dazu zwingen, zu (to compel to), unvermeidlich machen (to make inevitable — same meaning, slightly more everyday).","examples":[{"sentence":"Die Datenpanne machte eine Sicherheitsüberprüfung unumgänglich.","translation":"The data breach made a security review inescapable."},{"sentence":"Die Eskalation macht Verhandlungen unumgänglich.","translation":"The escalation makes negotiations inescapable."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Unumgänglich'' means?","options":["inescapable/unavoidable","necessary","inevitable","compulsory"],"correctAnswer":"inescapable/unavoidable"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The growing number of people in need of care poses barely manageable challenges to the care system and makes a fundamental restructuring of care financing inescapable.","options":["Die wachsende Zahl pflegebedürftiger Menschen stellt das Pflegesystem vor kaum bewältigbare Herausforderungen und macht einen grundlegenden Umbau der Pflegefinanzierung unumgänglich.","Das Pflegesystem ist überfordert und muss reformiert werden.","Die Pflegefinanzierung muss grundlegend reformiert werden.","Mehr Pflegebedürftige bedeuten mehr Belastung für das System."],"correctAnswer":"Die wachsende Zahl pflegebedürftiger Menschen stellt das Pflegesystem vor kaum bewältigbare Herausforderungen und macht einen grundlegenden Umbau der Pflegefinanzierung unumgänglich."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Datenpanne machte eine Sicherheitsüberprüfung ___.","options":["unumgänglich","notwendig","erforderlich","nötig"],"correctAnswer":"unumgänglich"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The escalation makes negotiations inescapable","wordBankItems":["Die","Eskalation","macht","Verhandlungen","unumgänglich","."],"correctAnswer":"Die Eskalation macht Verhandlungen unumgänglich ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Selbstbestimmt'' means?","options":["self-determined","autonomous","independent","self-directed"],"correctAnswer":"self-determined"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000021b',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss pension policy at B2","Use Rentenpolitik vocabulary","Talk about retirement age and pension reform"],"explanation":{"intro":"Pension policy vocabulary covers pension reform, intergenerational equity, and retirement funding at B2.","culturalNote":"Germany''s statutory pension insurance (gesetzliche Rentenversicherung): pay-as-you-go system (Umlageverfahren). Key issues: Rentenniveau (pension level — declining), Rentenbeitragssatz (contribution rate — rising), Renteneintrittsalter (retirement age — 67). Key reforms: Rentenreform 1992, Riester-Rente (private pension top-up), Grundrente (basic pension for low-income workers 2021). Bundesverband der Deutschen Rentenversicherung."},"examples":[{"german":"Das Umlageverfahren der gesetzlichen Rentenversicherung funktioniert, solange das Verhältnis von Beitragszahlern zu Rentenempfängern ausgewogen bleibt.","english":"The pay-as-you-go system of statutory pension insurance works as long as the ratio of contributors to pension recipients remains balanced."},{"german":"Eine Erhöhung des Renteneintrittsalters ist politisch unpopulär, gilt jedoch vielen Ökonomen als unvermeidlich, um das Rentensystem langfristig finanzierbar zu halten.","english":"Raising the retirement age is politically unpopular, but is regarded by many economists as unavoidable in order to keep the pension system financially viable in the long term."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss pension policy, retirement age, and pension reform at B2."}}',
'{"items":[{"word":"ausgewogen","translation":"balanced","pronunciation":"OWS-geh-voh-gen","example":"Ausgewogenes Verhältnis."},{"word":"das Verhältnis","translation":"ratio/relationship","pronunciation":"dahs fer-HÄLT-nis","example":"Verhältnis von Beitragszahlern."},{"word":"unpopulär","translation":"unpopular","pronunciation":"OON-po-poo-LÄR","example":"Politisch unpopulär."},{"word":"finanzierbar","translation":"financially viable/affordable","pronunciation":"fi-nan-TSEER-bahr","example":"Finanzierbar halten."},{"word":"der Ökonom","translation":"economist","pronunciation":"dayr ö-ko-NOM","example":"Viele Ökonomen."},{"word":"unvermeidlich","translation":"unavoidable/inevitable","pronunciation":"OON-fer-myd-likh","example":"Als unvermeidlich gelten."}]}',
'{"title":"Als unvermeidlich gelten — to be regarded as unavoidable","pattern":"als X gelten = to be considered/regarded as X (general status, not individual perception)","explanation":"Als X gelten = to be considered/regarded as X (expresses general consensus or status — more objective than als X angesehen werden which is more perception-based). Die Reform gilt als notwendig = The reform is considered necessary. Als unvermeidlich gelten = to be regarded as unavoidable. Perfect: hat gegolten. Compare: als X angesehen werden (to be regarded as — perception), als X bekannt sein (to be known as — factual reputation), als X bezeichnet werden (to be described as — labelling).","examples":[{"sentence":"Diese Methode gilt als überholt.","translation":"This method is considered outdated."},{"sentence":"Er gilt als einer der besten Pianisten seiner Generation.","translation":"He is regarded as one of the best pianists of his generation."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Ausgewogen'' means?","options":["balanced","even","proportionate","equilibrated"],"correctAnswer":"balanced"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Raising the retirement age is politically unpopular, but is regarded by many economists as unavoidable in order to keep the pension system financially viable in the long term.","options":["Eine Erhöhung des Renteneintrittsalters ist politisch unpopulär, gilt jedoch vielen Ökonomen als unvermeidlich, um das Rentensystem langfristig finanzierbar zu halten.","Das Rentenalter muss erhöht werden, obwohl es unpopulär ist.","Ökonomen befürworten eine Erhöhung des Renteneintrittsalters.","Das Rentensystem kann langfristig nur durch Reformen erhalten werden."],"correctAnswer":"Eine Erhöhung des Renteneintrittsalters ist politisch unpopulär, gilt jedoch vielen Ökonomen als unvermeidlich, um das Rentensystem langfristig finanzierbar zu halten."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Diese Methode gilt als ___.","options":["überholt","veraltet","antiquiert","altmodisch"],"correctAnswer":"überholt"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: He is regarded as one of the best pianists of his generation","wordBankItems":["Er","gilt","als","einer","der","besten","Pianisten","seiner","Generation","."],"correctAnswer":"Er gilt als einer der besten Pianisten seiner Generation ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Finanzierbar'' means?","options":["financially viable/affordable","fundable","payable","feasible"],"correctAnswer":"financially viable/affordable"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000021c',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss the generational contract at B2","Use Generationenvertrag vocabulary","Talk about intergenerational equity"],"explanation":{"intro":"Generational contract vocabulary covers intergenerational fairness, climate debt, and fiscal policy at B2.","culturalNote":"Generationenvertrag (generational contract) = intergenerational solidarity: working generations pay for pensioners, future generations bear public debt and climate change costs. Key debates: Generationengerechtigkeit (intergenerational equity), Schuldenbremse (debt brake — constitutional rule limiting German federal borrowing since 2009), Klimaschulden (climate debt — costs imposed on future generations), Bildungsinvestitionen für zukünftige Generationen."},"examples":[{"german":"Der Generationenvertrag impliziert eine Solidarität über die Zeit: Jede Generation profitiert von den Investitionen der Vorherigen und schuldet der nächsten eine intakte Umwelt und tragfähige Institutionen.","english":"The generational contract implies a solidarity over time: each generation benefits from the investments of the previous one and owes the next an intact environment and viable institutions."},{"german":"Generationengerechtigkeit erfordert, dass kurzfristige politische Gewinne nicht auf Kosten langfristiger Lasten für zukünftige Generationen erzielt werden.","english":"Intergenerational equity requires that short-term political gains are not achieved at the expense of long-term burdens for future generations."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss the generational contract, intergenerational equity, and climate debt at B2."}}',
'{"items":[{"word":"implizieren","translation":"to imply","pronunciation":"im-plee-TSEER-en","example":"Eine Solidarität implizieren."},{"word":"profitieren von","translation":"to benefit from","pronunciation":"pro-fi-TSEER-en fon","example":"Von Investitionen profitieren."},{"word":"schulden","translation":"to owe","pronunciation":"SHOOL-den","example":"Der nächsten Generation schulden."},{"word":"tragfähig","translation":"viable/sustainable","pronunciation":"TRAHK-fä-ikh","example":"Tragfähige Institutionen."},{"word":"kurzfristig","translation":"short-term","pronunciation":"KOORTS-fris-tikh","example":"Kurzfristige Gewinne."},{"word":"die Last","translation":"burden","pronunciation":"dee last","example":"Langfristige Lasten."}]}',
'{"title":"Schulden — to owe (someone something)","pattern":"jemandem etwas schulden = to owe someone something (dative + accusative construction)","explanation":"Schulden = to owe (dative + accusative). Jede Generation schuldet der nächsten eine intakte Umwelt = Each generation owes the next an intact environment. Dative = the creditor (person owed to), accusative = what is owed. Also used colloquially: eine Antwort schulden (to owe an answer), eine Erklärung schulden. Note: die Schuld (guilt/debt), die Schulden (plural = debts), schuldig sein (to be guilty/to owe — adj.). Compare: verdanken (to owe in the sense of ''I owe it to you'' = I have you to thank), verpflichtet sein (to be obliged to).","examples":[{"sentence":"Ich schulde Ihnen noch eine Antwort.","translation":"I still owe you an answer."},{"sentence":"Er schuldet ihr eine Erklärung für sein Verhalten.","translation":"He owes her an explanation for his behaviour."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Tragfähig'' means?","options":["viable/sustainable","load-bearing","stable","solid"],"correctAnswer":"viable/sustainable"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The generational contract implies a solidarity over time: each generation benefits from the investments of the previous one and owes the next an intact environment and viable institutions.","options":["Der Generationenvertrag impliziert eine Solidarität über die Zeit: Jede Generation profitiert von den Investitionen der Vorherigen und schuldet der nächsten eine intakte Umwelt und tragfähige Institutionen.","Jede Generation schuldet der nächsten eine bessere Welt.","Der Generationenvertrag verbindet Vergangenheit, Gegenwart und Zukunft.","Solidarität zwischen Generationen bedeutet gegenseitige Verantwortung."],"correctAnswer":"Der Generationenvertrag impliziert eine Solidarität über die Zeit: Jede Generation profitiert von den Investitionen der Vorherigen und schuldet der nächsten eine intakte Umwelt und tragfähige Institutionen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich schulde Ihnen noch eine ___.","options":["Antwort","Reaktion","Rückmeldung","Antwort"],"correctAnswer":"Antwort"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: He owes her an explanation for his behaviour","wordBankItems":["Er","schuldet","ihr","eine","Erklärung","für","sein","Verhalten","."],"correctAnswer":"Er schuldet ihr eine Erklärung für sein Verhalten ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Profitieren von'' means?","options":["to benefit from","to profit from","to gain from","to advantage from"],"correctAnswer":"to benefit from"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

